import{_ as e,o as d,c as s,a2 as r}from"./chunks/framework.CRfKVJQk.js";const a="/react-native-glass-effect/assets/glass-demo-android.BAgqY-z6.gif",i="/react-native-glass-effect/assets/glass-demo-ios.DswMmFHF.gif",f=JSON.parse('{"title":"Platform support","description":"","frontmatter":{},"headers":[],"relativePath":"reference/platform-support.md","filePath":"reference/platform-support.md"}'),o={name:"reference/platform-support.md"};function n(l,t,h,p,c,u){return d(),s("div",null,[...t[0]||(t[0]=[r('<h1 id="platform-support" tabindex="-1">Platform support <a class="header-anchor" href="#platform-support" aria-label="Permalink to &quot;Platform support&quot;">​</a></h1><h2 id="feature-matrix" tabindex="-1">Feature matrix <a class="header-anchor" href="#feature-matrix" aria-label="Permalink to &quot;Feature matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Android 13+</th><th>Android 12</th><th>Android 7–11</th><th>iOS 26+</th><th>iOS 15–25</th><th>Web</th><th>Expo Go</th></tr></thead><tbody><tr><td>Live background blur</td><td>✅ GPU</td><td>✅ GPU</td><td>✅ snapshot (throttled)</td><td>✅ system</td><td>✅ system</td><td>✅ CSS</td><td>—</td></tr><tr><td>Edge refraction / lens</td><td>✅</td><td>—</td><td>—</td><td>✅ system</td><td>—</td><td>—</td><td>—</td></tr><tr><td>RGB split at edges</td><td>✅ (<code>high</code>)</td><td>—</td><td>—</td><td>—</td><td>—</td><td>—</td><td>—</td></tr><tr><td>Rim lighting</td><td>✅ shader</td><td>✅ approx.</td><td>✅ approx.</td><td>✅ system</td><td>✅ sheen</td><td>—</td><td>—</td></tr><tr><td>Touch-follow light</td><td>✅</td><td>✅</td><td>✅</td><td>✅ system (<code>interactive</code>)</td><td>—</td><td>—</td><td>—</td></tr><tr><td>Press squish</td><td>✅ native</td><td>✅ native</td><td>✅ native</td><td>✅ system</td><td>✅ JS</td><td>✅ JS</td><td>✅ JS</td></tr><tr><td>Tilt lighting</td><td>✅</td><td>✅</td><td>✅</td><td>—</td><td>—</td><td>—</td><td>—</td></tr><tr><td>Animated prop changes</td><td>✅</td><td>✅</td><td>✅</td><td>✅ effect</td><td>✅ effect</td><td>—</td><td>—</td></tr><tr><td>Needs <code>&lt;GlassBackdrop&gt;</code></td><td>yes</td><td>yes</td><td>yes</td><td>no (yes with <code>iosRenderer=&quot;shader&quot;</code>)</td><td>no (yes with <code>iosRenderer=&quot;shader&quot;</code>)</td><td>no</td><td>no</td></tr><tr><td>Video/maps in TextureView</td><td>✅</td><td>✅</td><td>—</td><td>✅</td><td>✅</td><td>—</td><td>—</td></tr><tr><td>Video/maps in SurfaceView</td><td>—</td><td>—</td><td>—</td><td>n/a</td><td>n/a</td><td>—</td><td>—</td></tr></tbody></table><p>&quot;—&quot; means the prop is accepted and ignored, never an error. The iOS columns are for the default <code>iosRenderer=&quot;system&quot;</code>. With <code>iosRenderer=&quot;shader&quot;</code>, iOS behaves like Android 13+.</p><p><strong>Expo dev builds</strong> use the Android and iOS columns. <strong>Web</strong> covers React (Vite), Next.js (including server rendering) and Expo web.</p><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Minimum</th></tr></thead><tbody><tr><td>React Native</td><td>0.76, New Architecture</td></tr><tr><td>Android</td><td>minSdk 24 (Android 7)</td></tr><tr><td>iOS</td><td>15.1. Apple&#39;s Liquid Glass needs iOS 26, built with Xcode 26</td></tr><tr><td>Web</td><td><code>react-native-web</code> 0.19+ and a browser with <code>backdrop-filter</code> for blur</td></tr></tbody></table><h2 id="tested-setups" tabindex="-1">Tested setups <a class="header-anchor" href="#tested-setups" aria-label="Permalink to &quot;Tested setups&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setup</th><th>Versions</th><th>Checked</th></tr></thead><tbody><tr><td>Expo dev build, Android emulator</td><td>Expo SDK 58, React Native 0.88</td><td>Every example on this site renders natively; buttons and the adjuster respond to taps</td></tr><tr><td>Expo web</td><td>Expo SDK 58, react-native-web 0.21</td><td>Dev server and production export render; buttons work; no console errors</td></tr><tr><td>Vite</td><td>Vite 8, React 19, react-native-web 0.21</td><td>Every example on this site renders; no console errors</td></tr><tr><td>Next.js</td><td>Next.js 16 (App Router, Turbopack)</td><td><code>next build</code> prerenders; the browser hydrates; buttons work</td></tr></tbody></table><p>Not yet tested: iOS devices and simulators in these setups, EAS Build, Expo Go beyond the fallback.</p><h2 id="why-platforms-look-different" tabindex="-1">Why platforms look different <a class="header-anchor" href="#why-platforms-look-different" aria-label="Permalink to &quot;Why platforms look different&quot;">​</a></h2><p>By default iOS uses Apple&#39;s own glass and Android uses the library&#39;s renderer, so they look clearly different: Apple&#39;s glass is lighter and paler. For a matching look:</p><ul><li>Use <a href="/react-native-glass-effect/components/frosted-glass"><code>&lt;FrostedGlass&gt;</code></a>: the same shader on both.</li><li>Use <a href="/react-native-glass-effect/components/liquid-glass"><code>&lt;LiquidGlass&gt;</code></a>: Android tuned to match Apple&#39;s glass.</li><li>Or tune per platform:</li></ul><div class="language-tsx vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">tsx</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">LiquidGlassView</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> blur</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{Platform.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">OS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> ===</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;android&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> ?</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 24</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> :</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 20</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">} /&gt;</span></span></code></pre></div><h2 id="recordings" tabindex="-1">Recordings <a class="header-anchor" href="#recordings" aria-label="Permalink to &quot;Recordings&quot;">​</a></h2><p>Recordings of the example app with <code>iosRenderer: &#39;shader&#39;</code> in the theme, so both platforms use the same renderer:</p><table tabindex="0"><thead><tr><th>Android</th><th>iOS</th></tr></thead><tbody><tr><td><a href="https://raw.githubusercontent.com/SachinMeenaSipl/react-native-glass-effect/v0.2.0/docs/videos/glass-demo-android.mp4" target="_blank" rel="noreferrer"><img src="'+a+'" alt="Glass demo on Android"></a></td><td><a href="https://raw.githubusercontent.com/SachinMeenaSipl/react-native-glass-effect/v0.2.0/docs/videos/glass-demo-ios.mp4" target="_blank" rel="noreferrer"><img src="'+i+'" alt="Glass demo on iOS"></a></td></tr></tbody></table>',17)])])}const g=e(o,[["render",n]]);export{f as __pageData,g as default};
